/* eslint-disable @typescript-eslint/ban-ts-comment -- the build output may or may not exist when type-checking */
// Worker entry point: requests go to the OpenNext handler, cron ticks to runCron.
// `.open-next/worker.js` is generated by `opennextjs-cloudflare build`.
// @ts-ignore: generated at build time
import handler from "./.open-next/worker.js";
import { runCron } from "./lib/jobs/cron";

// Durable Objects OpenNext defines; wrangler needs them exported from the entry point.
// @ts-ignore: generated at build time
export { BucketCachePurge, DOQueueHandler, DOShardedTagCache } from "./.open-next/worker.js";

export default {
  fetch: handler.fetch,
  async scheduled(controller: ScheduledController, env: CloudflareEnv, ctx: ExecutionContext) {
    ctx.waitUntil(runCron(env as never, new Date(controller.scheduledTime)));
  },
} satisfies ExportedHandler<CloudflareEnv>;
